#define dequantize_q6_k(qs16, qh16, a_f16, scale) \
    a_f16.s0 = (half)(((float)(( qs16.s0 & 0x000F)        | ((uint)(( qh16       ) & 0x3) << 4)) - 32.f) * scale); \
