                         dmin * (sumy.s0 * sc8[2] + sumy.s1 * sc8[3] + sumy.s2 * sc8[6] + sumy.s3 * sc8[7]);

            q1  += nb01/2;
            sc  += nb01/2;
            dh  += nb01/2;
